/** Primary lockup: symbol + wordmark with the level cut. Min width 110px. */
export function Logo({
  height = 20,
  color = "forest",
  className,
}: {
  height?: number;
  color?: LogoColor;
  className?: string;
}) {
  const id = useId().replace(/:/g, "");
  const fill = FILL[color];
  const width = (5236 / 686) * height;
  return (
    <svg
      viewBox="0 0 5236 686"
      width={width}
      height={height}
      role="img"
      aria-label="TRAKTOR"
      className={className}
      style={{ display: "block", flex: "0 0 auto" }}
    >
      <defs>
        <mask id={`lv${id}`} maskUnits="userSpaceOnUse" x="-9999" y="-9999" width="30000" height="30000">
          <rect x="-9999" y="-9999" width="30000" height="30000" fill="#fff" />
          <rect x="-9999" y="216.1" width="30000" height="41.2" fill="#000" />
        </mask>
      </defs>
      <g transform="scale(22.12903) translate(0 -7.0)">
        <path d={GROUND} fill="none" stroke={fill} strokeWidth={6} strokeMiterlimit={10} />
        <path d={BOARD} fill={fill} />
      </g>
      <path transform="translate(1297 0)" d={WORDMARK} fill={fill} mask={`url(#lv${id})`} />
    </svg>
  );
}

/** Symbol only: ditch in section + board. Min 24px on screen. */
export function LogoSymbol({
  size = 32,
  color = "forest",
  className,
}: {
  size?: number;
  color?: LogoColor;
  className?: string;
}) {
  const fill = FILL[color];
  return (
    <svg
      viewBox="0 7 48 31"
      width={size}
      height={(size * 31) / 48}
      aria-hidden="true"
      className={className}
      style={{ display: "block", flex: "0 0 auto" }}
    >
      <path d={GROUND} fill="none" stroke={fill} strokeWidth={6} strokeMiterlimit={10} />
      <path d={BOARD} fill={fill} />
    </svg>
  );
}
